{"command": "python -c "
import sqlparse
tests = [
    'SELECT * FROM foo WHERE (a WHERE b',
    'SELECT * FROM foo WHERE a IN (SELECT * FROM bar WHERE (c',
    'SELECT * FROM foo WHERE (SELECT * FROM bar WHERE (c',
    'SELECT * FROM foo WHERE (SELECT * FROM bar WHERE c) AND (d',
]
for t in tests:
    try:
        r = sqlparse.format(t, reindent=True)
        print('OK:', repr(t), '->', repr(r))
    except Exception as e:
        print('FAIL:', repr(t), '->', type(e).__name__, e)
"", "timeout_seconds": 30}

